import SwiftUI

struct ConversationListView: View {
    @EnvironmentObject private var store: ConversationStore
    @AppStorage("selectedModel") private var selectedModel: String = ""
    @State private var selectedId: UUID?
    @State private var showSettings = false

    var body: some View {
        NavigationSplitView {
            List(selection: $selectedId) {
                ForEach(store.conversations) { conv in
                    NavigationLink(value: conv.id) {
                        VStack(alignment: .leading, spacing: 2) {
                            Text(conv.title)
                                .lineLimit(1)
                            Text(conv.modelId.isEmpty ? "no model" : conv.modelId)
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .lineLimit(1)
                        }
                    }
                }
                .onDelete(perform: store.delete)
            }
            .navigationTitle("Fornax")
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    Button { showSettings = true } label: {
                        Image(systemName: "gear")
                    }
                }
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        let c = store.newConversation(modelId: selectedModel)
                        selectedId = c.id
                    } label: {
                        Image(systemName: "square.and.pencil")
                    }
                }
            }
            .sheet(isPresented: $showSettings) { SettingsView() }
        } detail: {
            if let id = selectedId, let conv = store.conversations.first(where: { $0.id == id }) {
                ChatView(conversation: conv) { updated in
                    store.update(updated)
                }
                .id(id)
            } else {
                ContentUnavailableView("Select a chat", systemImage: "bubble.left.and.bubble.right")
            }
        }
    }
}

